<?php require_once __DIR__.'/includes/bootstrap.php';require_login();$errors=[];$title='';$description='';$location='';$event_date='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$title=trim($_POST['title']??'');$description=trim($_POST['description']??'');$location=trim($_POST['location']??'');$event_date=$_POST['event_date']??'';if(mb_strlen($title)<3||mb_strlen($title)>150)$errors[]='Title must be between 3 and 150 characters.';if(mb_strlen($description)>5000)$errors[]='Description is too long.';if(mb_strlen($location)>200)$errors[]='Location must be 200 characters or fewer.';if(!valid_date($event_date))$errors[]='Choose a valid event date and time.';if(!$errors){$s=$pdo->prepare('INSERT INTO events(user_id,title,description,location,event_date) VALUES(?,?,?,?,?)');$s->execute([$_SESSION['user_id'],$title,$description,$location,str_replace('T',' ',$event_date).':00']);flash('success','Event created successfully.');redirect('/dashboard.php');}}$page_title='Create event';require __DIR__.'/includes/header.php'; ?>
<section class="panel form-panel wide-form"><a class="back-link" href="dashboard.php">← Dashboard</a><h1>Create Event</h1><p class="muted">Add the details for your upcoming event.</p><?php foreach($errors as $err): ?><div class="alert error"><?= e($err) ?></div><?php endforeach; ?><form method="post" data-validate><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label>Event title<input name="title" required minlength="3" maxlength="150" value="<?= e($title) ?>"></label><label>Description<textarea name="description" rows="5" maxlength="5000"><?= e($description) ?></textarea></label><label>Location<input name="location" maxlength="200" value="<?= e($location) ?>" required></label><label>Date and time<input type="datetime-local" name="event_date" required value="<?= e($event_date) ?>"></label><button class="button primary" type="submit">Create Event</button></form></section><?php require __DIR__.'/includes/footer.php'; ?>